from typing import Dict, List, Optional, Tuple
from collections import Counter, OrderedDict, defaultdict, deque
import heapq

def letter_case_permutation(s: str) -> list[str]:
    out: list[str] = []
    path: list[str] = []

    def dfs(i: int) -> None:
        if i == len(s):
            out.append("".join(path))
            return
        ch = s[i]
        if ch.isdigit():
            path.append(ch)
            dfs(i + 1)
            path.pop()
        else:
            for variant in (ch.lower(), ch.upper()):
                path.append(variant)
                dfs(i + 1)
                path.pop()

    dfs(0)
    return sorted(out)

